import * as G from './game.js';
import {initBoard,initDie} from './board.js';
import {POINT_COLORS} from './paint.js';
const $=id=>document.getElementById(id),esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=s=>`<i class="sense-icon" style="--i:${G.SENSES.indexOf(s)}" aria-hidden="true"></i>`;
const tileColor=v=>POINT_COLORS[v]||'#ffe14a';
let game,board,die,busy=false,challenge=null,repair=null,repairPart=0,digits=[],resultInfo=null;
let prefs={calm:matchMedia('(prefers-reduced-motion: reduce)').matches,sound:false};
try{game=G.restoreGame(localStorage.getItem('five-senses-game'));prefs={...prefs,...JSON.parse(localStorage.getItem('five-senses-prefs')||'{}')};}catch{}
game ||=G.freshGame();
function save(){try{localStorage.setItem('five-senses-game',JSON.stringify(game));}catch{toast('Browser storage is unavailable. Keep this tab open to keep playing.');}}
function log(msg){game.log=Array.isArray(game.log)?game.log:[];game.log.unshift(msg);game.log=game.log.slice(0,8);save();}
function toast(msg){$('toast').textContent=msg;$('toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('toast').classList.remove('show'),4000);}
function sound(kind='tap'){if(!prefs.sound)return;try{const ac=sound.ctx||=new (window.AudioContext||window.webkitAudioContext)();ac.resume();const o=ac.createOscillator(),gain=ac.createGain();o.type='sine';o.frequency.value=kind==='good'?660:kind==='bad'?180:380;gain.gain.setValueAtTime(.045,ac.currentTime);gain.gain.exponentialRampToValueAtTime(.001,ac.currentTime+.2);o.connect(gain).connect(ac.destination);o.start();o.stop(ac.currentTime+.2);}catch{}}
function randomD20(){const a=new Uint32Array(1);do{crypto.getRandomValues(a);}while(a[0]>=4294967280);return a[0]%20+1;}
function applyPrefs(){document.body.classList.toggle('calm',prefs.calm);board?.setCalm(prefs.calm);$('calmToggle').checked=prefs.calm;$('soundToggle').checked=prefs.sound;try{localStorage.setItem('five-senses-prefs',JSON.stringify(prefs));}catch{}}
try{board=initBoard($('canvasWrap'));board.sync(game);$('loading').remove();}catch(e){console.error('3D board unavailable',e);$('loading').remove();$('boardFallback').hidden=false;$('stage').style.minHeight='180px';document.querySelector('.route-details').open=true;}
applyPrefs();
function renderChrome(){game.players.forEach((p,i)=>{$(`name${i}`).textContent=p.name;$(`position${i}`).textContent=p.pos===0?'START · SPACE 0 / 24':p.pos===24?'HOME AT THE CORE':`SPACE ${p.pos} / 24`;$(`score${i}`).textContent=p.score;$(`player${i}`).classList.toggle('active',game.active===i&&!['won','lost'].includes(game.phase));});document.body.dataset.turn=game.active;$('roundLabel').textContent=`TURN ${String(game.turn).padStart(2,'0')}`;$('beaconCount').textContent=`${game.beacons.filter(Boolean).length} of 5 restored`;$('beacons').innerHTML=G.SENSES.map((s,i)=>`<div class="beacon-pill ${game.beacons[i]?'on':''}" style="--c:var(--sense-${i})" title="${s.name}: ${game.beacons[i]?'restored':'waiting at space '+G.GATES[i]}">${icon(s)}<span class="beacon-name">${s.verb}</span><span class="tick">${game.beacons[i]?'✓ ON':'SPACE '+G.GATES[i]}</span></div>`).join('');$('energy').classList.toggle('low',game.energy===1);$('energy').innerHTML=Array.from({length:3},(_,i)=>`<span class="${i<game.energy?'on':''}"></span>`).join('');$('energy').setAttribute('aria-label',`${game.energy} of 3 shared power remaining`);$('powerNote').textContent=game.energy===0?'The connection is lost.':game.energy===1?'Low power. Recharge soon.':'Keep the connection alive.';$('activity').innerHTML=(game.log||[]).slice(0,4).map(t=>`<li>${esc(t)}</li>`).join('');$('routeList').innerHTML=Array.from({length:25},(_,i)=>{const names=game.players.filter(p=>p.pos===i).map(p=>p.name);const gate=G.GATES.indexOf(i);return `<span class="${names.length?'occupied':''} ${gate>=0&&!game.beacons[gate]?'locked':''}">${i===0?'Start':i===24?'Core':i}${gate>=0?' · '+G.SENSES[gate].name+(game.beacons[gate]?' ✓':' ◇'):''}${names.length?' — '+names.map(esc).join(' & '):''}</span>`;}).join('');board?.sync(game);}
const badge=(text,team=false)=>`<div class="action-eyebrow ${team?'team':'p'+game.active}"><i></i>${esc(text)}</div>`;
const button=(action,text,secondary=false)=>`<button class="${secondary?'secondary':'primary'}" data-action="${action}">${text}${secondary?'':'<span>↗</span>'}</button>`;
function setAction(html){die?.dispose();die=null;$('action').innerHTML=html;const main=$('action').querySelector('.primary');$('jumpBtn').querySelector('span').textContent=main?main.firstChild.textContent.trim():'Your move';}
function render(){renderChrome();const p=game.players[game.active],n=esc(p.name),team=badge('A MOMENT FOR BOTH OF YOU',true);switch(game.phase){
case 'roll':setAction(`${badge(`${p.name.toUpperCase()}’S TURN`)}<h2>Your next little leap.</h2><p>One roll. A new connection.<br>The core is ${24-p.pos} spaces away.</p><div class="die-wrap" id="die"><span class="die-fallback" aria-hidden="true">${game.lastRoll||20}</span></div><p class="die-tip">A NATURAL 20 EARNS +5 BONUS POINTS</p><div class="roll-map"><span>1–5<b>1 step</b></span><span>6–10<b>2 steps</b></span><span>11–15<b>3 steps</b></span><span>16–20<b>4 steps</b></span></div>${button('roll','Roll the d20')}${game.energy<3?button('recover','Recharge instead · +1 power',true):''}`);try{$('die').innerHTML='';die=initDie($('die'));die.set(game.lastRoll||20);}catch{$('die').innerHTML=`<span class="die-fallback">${game.lastRoll||20}</span>`;}break;
case 'choose':{const s=G.SENSES[game.pending.sense];setAction(`${badge('LANDED ON SPACE '+p.pos)}<div class="landing-chip" style="--c:var(--sense-${G.SENSES.indexOf(s)})">${icon(s)} ${s.name} snapshot</div><h2>Play it safe.<br>Or be a little bold.</h2><p>${n}, memorize a few ${s.name.toLowerCase()}-themed cards, then answer one question about their order. No timer.</p><button class="choice-card" data-action="safe"><span><b>Steady steps</b><small>3 cards · no points lost if wrong</small></span><span class="reward" style="--tile:${tileColor(G.rewardAt(p.pos))}">+${G.rewardAt(p.pos)}</span></button><button class="choice-card" data-action="bold"><span><b>A bold connection</b><small>5 cards · lose 5 points if wrong</small></span><span class="reward" style="--tile:${tileColor(G.rewardAt(p.pos)+10)}">+${G.rewardAt(p.pos)+10}</span></button><div class="repair-tip">Solo moment: the other player can watch, but let ${n} choose the answer.</div>`);break;}
case 'challenge':showMemory();break;
case 'repair':showRepair();break;
case 'result':{const r=resultInfo||{correct:true,delta:0,reloaded:true};setAction(`${badge('SNAPSHOT COMPLETE')}<div class="result-icon ${r.correct?'':'bad'}">${r.correct?'✓':'↺'}</div><h2>${r.reloaded?'Turn complete.':r.correct?'A clear connection.':'A little practice helps.'}</h2><div class="points-result ${r.correct?'':'bad'}">${r.reloaded?'':(r.delta>=0?'+':'')+r.delta}<span style="font-size:13px;letter-spacing:0">${r.reloaded?'Score saved':' points'}</span></div><p>${r.reloaded?'Your score has been saved. Continue when you’re ready.':`${r.correct?'':`You picked <b>${esc(r.picked)}</b>. `}Card ${challenge.index+1} was <b>${esc(challenge.answer)}</b>. ${r.correct?'Nicely remembered.':'There’s another chance around the corner.'}`}</p>${button('next','Pass the turn')}`);break;}
case 'repaired':setAction(`${team}<div class="result-icon">✳</div><h2>${G.SENSES[game.pending.gate].name} is back online.</h2><div class="points-result">+10 <span style="font-size:13px;letter-spacing:0">each</span></div><p>Two little contributions. One big connection. ${game.beacons.filter(Boolean).length} of 5 beacons restored.</p>${button('next','Keep the connection going')}`);break;
case 'repair-failed':setAction(`${team}<div class="result-icon bad">↺</div><h2>A crossed connection.</h2><p>The code didn’t match. Shared power is now <b>${game.energy} / 3</b>. Take your time with a new code; you can talk and plan together.</p><div class="repair-tip">Both players enter exactly two digits. ${esc(game.players[0].name)} takes positions 1–2; ${esc(game.players[1].name)} takes positions 3–4.</div>${button('retry','Try a new repair code')}`);break;
case 'arrived':setAction(`${badge('HOME AT THE CORE')}<div class="result-icon">⌂</div><h2>Welcome home, ${n}.</h2><div class="points-result">+10 <span style="font-size:13px;letter-spacing:0">points</span></div><p>${game.players.every(p=>p.pos===24)?'You both made it. The whole network is connected.':'Your explorer rests here. Your partner keeps taking turns until they reach the core too.'}</p>${button('next',game.players.every(p=>p.pos===24)?'See the final scores':'Cheer your partner home')}`);break;
case 'recovered':setAction(`${badge('A TURN WELL SPENT')}<div class="result-icon">ϟ</div><h2>A little energy.<br>For everyone.</h2><p>${n} stayed in place and restored 1 shared power. The network now has <b>${game.energy} / 3</b> power.</p>${button('next','Pass the turn')}`);break;
case 'won':{const [a,b]=game.players,winner=a.score===b.score?null:a.score>b.score?a:b;setAction(`${team}<div class="result-icon">♛</div><h2>${winner?esc(winner.name)+' takes the crown.':'A shared crown.'}</h2><p>You both reached the core and restored every sense. That’s the real connection.</p><div class="winner-names">${game.players.map(p=>`<div><span>${esc(p.name)}</span><b>${p.score}</b></div>`).join('')}</div><p>${winner?'Highest score wins the friendly rivalry.':'Equal scores. Equal bragging rights.'}</p>${button('new','Another journey?')}`);break;}
case 'lost':setAction(`${team}<div class="result-icon bad">○</div><h2>The garden<br>has gone quiet.</h2><p>Shared power reached zero. Neither player wins this time. Next game, use a recharge turn before your power gets low.</p><div class="winner-names">${game.players.map(p=>`<div><span>${esc(p.name)}</span><b>${p.score}</b></div>`).join('')}</div>${button('new','Bring the garden back')}`);break;
}}
function showMemory(){if(!challenge)challenge=G.makeChallenge(game.pending.sense,game.pending.level);const s=G.SENSES[game.pending.sense];setAction(`${badge('A '+s.name.toUpperCase()+' SNAPSHOT')}<h2>Take a little look.</h2><p>Remember these cards <b>in order</b>. You can look as long as you need. When ready, hide the cards.</p><div class="memory-cards ${game.pending.level==='bold'?'bold':''}">${challenge.items.map((v,i)=>`<div class="memory-card"><span>${i+1}</span><b>${esc(v)}</b></div>`).join('')}</div><p>${s.name==='Hearing'?'These are sound words. No audio is needed.':s.name==='Smell'||s.name==='Taste'?'Imagine the words; no real objects or food needed.':'Remember the words and where they appear.'}</p>${button('hide','I’m ready · hide the cards')}`);}
function showQuestion(){setAction(`${badge('TRUST YOUR MEMORY')}<h2>What was card<br>number ${challenge.index+1}?</h2><div class="memory-cards recall">${challenge.items.map((_,i)=>`<div class="memory-card ${i===challenge.index?'ask':''}"><span>${i+1}</span><b>${i===challenge.index?'?':'·'}</b></div>`).join('')}</div><p>${esc(game.players[game.active].name)}, choose the word that was in slot ${challenge.index+1} (counting left to right).</p><div class="option-grid">${challenge.options.map((v,i)=>`<button data-action="answer" data-value="${i}">${esc(v)}</button>`).join('')}</div><p>${game.pending.level==='bold'?('Correct +'+(G.rewardAt(game.players[game.active].pos)+10)+' · wrong −5'):('Correct +'+G.rewardAt(game.players[game.active].pos)+' · wrong 0')} · no timer.</p>`);}
function showRepair(){if(!repair)repair=G.makeRepair(game.pending.gate);repairPart=0;digits=[];const s=G.SENSES[game.pending.gate];setAction(`${badge('SHARED BEACON · SPACE '+G.GATES[game.pending.gate],true)}<div class="landing-chip" style="--c:var(--sense-${G.SENSES.indexOf(s)})">${icon(s)} ${s.name} beacon</div><h2>It takes two<br>to reconnect.</h2><p>An unrestored beacon stops the move here. Memorize this code together; each of you will enter half.</p><div class="repair-code">${repair.code.map(v=>`<span>${v}</span>`).join('')}</div><p><b>${esc(game.players[0].name)}</b> takes the first two digits.<br><b>${esc(game.players[1].name)}</b> takes the last two.</p><div class="repair-tip">Talk it through. No timer. One wrong code costs 1 shared power. Both earn +10 for a successful repair.</div>${button('repair-start','We’re ready · hide the code')}`);}
function showKeypad(){const p=game.players[repairPart];setAction(`${badge('RECONNECT · PART '+(repairPart+1)+' OF 2',true)}<h2>${esc(p.name)},<br>your connection.</h2><p>Enter the <b>${repairPart===0?'first':'last'} two digits</b> of the code, in order. Your partner may help.</p><div class="digit-slots"><span>${digits[0]||'·'}</span><span>${digits[1]||'·'}</span></div><div class="repair-keypad">${[1,2,3,4].map(v=>`<button data-action="digit" data-value="${v}" aria-label="Enter digit ${v}">${v}</button>`).join('')}</div>${digits.length?button('undo','Undo last digit',true):''}<div class="repair-tip">Power: ${game.energy} / 3. The full code is checked after both players enter their half.</div>`);}
async function roll(){if(busy||game.phase!=='roll')return;busy=true;const btn=$('action').querySelector('[data-action="roll"]');btn.disabled=true;btn.innerHTML='Rolling…';$('action').querySelector('[data-action="recover"]')?.setAttribute('disabled','');const v=randomD20(),from=game.players[game.active].pos;const d=die;try{await d?.roll(v,prefs.calm);const move=G.rollTurn(game,v);save();sound(v===20?'good':'tap');if(!$('die').querySelector('canvas'))$('die').innerHTML=`<span class="die-fallback">${v}</span>`;btn.innerHTML=`${v} rolled · ${G.movement(v)} ${G.movement(v)===1?'step':'steps'}`;await board?.animateMove(game.active,from,move.dest);log(`${game.players[game.active].name} rolled ${v} → space ${move.dest}.${v===20?' Natural 20! +5 points.':''}`);challenge=null;repair=null;resultInfo=null;render();}finally{busy=false;}}
$('action').addEventListener('click',e=>{const el=e.target.closest('button[data-action]');if(!el||busy)return;const a=el.dataset.action;if(a==='roll'){roll();return;}sound();if(a==='safe'||a==='bold'){G.chooseChallenge(game,a);challenge=G.makeChallenge(game.pending.sense,a);save();render();}else if(a==='hide'){showQuestion();}else if(a==='answer'){const picked=challenge.options[Number(el.dataset.value)],correct=picked===challenge.answer;const delta=G.resolveChallenge(game,correct);resultInfo={correct,delta,picked};log(`${game.players[game.active].name}: ${correct?'snapshot remembered':'snapshot missed'} (${delta>=0?'+':''}${delta} points).`);sound(correct?'good':'bad');render();}else if(a==='next'){G.nextTurn(game);save();challenge=null;repair=null;render();}else if(a==='recover'){G.recover(game);log(`${game.players[game.active].name} recharged the network. Power ${game.energy}/3.`);render();}else if(a==='retry'){G.retryRepair(game);repair=null;save();render();}else if(a==='repair-start'){digits=[];repairPart=0;showKeypad();}else if(a==='digit'){if(digits.length>=2)return;digits.push(Number(el.dataset.value));if(digits.length<2)showKeypad();else if(repairPart===0){repair.first=[...digits];repairPart=1;digits=[];setAction(`${badge('HAND THE CONNECTION OVER',true)}<div class="result-icon">⇄</div><h2>Halfway there.</h2><p>${esc(game.players[0].name)}’s two digits are locked in. Pass to ${esc(game.players[1].name)} for the final two.</p>${button('repair-second',esc(game.players[1].name)+' is ready')}`);}else{const entered=[...repair.first,...digits],correct=entered.every((v,i)=>v===repair.code[i]);G.resolveRepair(game,correct);log(correct?`${G.SENSES[game.pending.gate].name} restored together. +10 each!`:`Repair missed. Shared power ${game.energy}/3.`);sound(correct?'good':'bad');render();}}else if(a==='repair-second'){showKeypad();}else if(a==='undo'){digits.pop();showKeypad();}else if(a==='new')openSettings();});
function openSettings(){$('input0').value=game.players[0].name;$('input1').value=game.players[1].name;$('resetConfirm').checked=false;$('newGameBtn').disabled=true;$('settingsDialog').showModal();}
$('rulesBtn').addEventListener('click',()=>$('rulesDialog').showModal());$('settingsBtn').addEventListener('click',openSettings);document.querySelectorAll('[data-close]').forEach(el=>el.addEventListener('click',()=>$(el.dataset.close).close()));document.querySelectorAll('dialog').forEach(dialog=>dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close();}}));$('resetConfirm').addEventListener('change',()=>{$('newGameBtn').disabled=!$('resetConfirm').checked;});$('newGameBtn').addEventListener('click',()=>{if(!$('resetConfirm').checked||busy)return;game=G.freshGame([$('input0').value,$('input1').value]);game.log=[`${game.players[0].name} & ${game.players[1].name}: a new journey begins.`];challenge=repair=resultInfo=null;save();$('settingsDialog').close();render();toast('A fresh table. A new connection.');});$('calmToggle').addEventListener('change',e=>{prefs.calm=e.target.checked;applyPrefs();});$('soundToggle').addEventListener('change',e=>{prefs.sound=e.target.checked;applyPrefs();sound();});$('viewBtn').addEventListener('click',()=>{const overhead=board?.toggleView();$('viewBtn').setAttribute('aria-label',overhead?'Switch to angled view':'Switch to overhead view');});$('resetViewBtn').addEventListener('click',()=>board?.resetView());$('zoomInBtn').addEventListener('click',()=>board?.zoom(-1.6));$('zoomOutBtn').addEventListener('click',()=>board?.zoom(1.6));
const jumpObserver=new IntersectionObserver(([entry])=>{$('jumpBtn').hidden=entry.isIntersecting||entry.boundingClientRect.top<0;},{threshold:.35});jumpObserver.observe($('action'));$('jumpBtn').addEventListener('click',()=>$('action').scrollIntoView({behavior:prefs.calm?'auto':'smooth',block:'center'}));
render();
